def remaining(maximum):
    reserve = 0 if FINALIZING else EVIDENCE_RESERVE_SECONDS
    value = min(maximum, DEADLINE - time.monotonic() - reserve)
    if value <= 0:
        raise TimeoutError("single additional-gate absolute budget exhausted")
    return value

